<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { actOnAdminResource, getAdminResources, type ResourceType } from '@/api/admin'
import type { ParkingLot, SpaceType } from '@/types/parking'
import { LOT_STATUS, SPACE_STATUS, SPACE_TYPE } from '@/constants/enums'
import StatusTag from '@/components/common/StatusTag.vue'

interface Row { id:number; status?:number; parkingLotId?:number; lotName?:string; lotCode?:string; address?:string; contactPhone?:string; businessStartTime?:string; businessEndTime?:string; description?:string; totalSpaces?:number; availableSpaces?:number; temporaryPrice?:number; spaceCode?:string; spaceType?:SpaceType; currentPlateNumber?:string; freeMinutes?:number; firstHourPrice?:number; additionalHourPrice?:number; dailyCapAmount?:number }
interface ResourceForm { status:number; parkingLotId?:number; lotName:string; lotCode:string; address:string; contactPhone:string; businessStartTime:string; businessEndTime:string; description:string; totalSpaces:number; availableSpaces:number; temporaryPrice:number; spaceCode:string; spaceType:SpaceType; currentPlateNumber:string; freeMinutes:number; firstHourPrice:number; additionalHourPrice:number; dailyCapAmount:number }
const type=ref<ResourceType>('PARKING_LOT');const rows=ref<Row[]>([]);const lots=ref<ParkingLot[]>([]);const loading=ref(false);const dialog=ref(false);const editingId=ref<number>();
const defaults=():ResourceForm=>({status:1,parkingLotId:undefined,lotName:'',lotCode:'',address:'',contactPhone:'',businessStartTime:'00:00',businessEndTime:'23:59',description:'',totalSpaces:0,availableSpaces:0,temporaryPrice:5,spaceCode:'',spaceType:'NORMAL',currentPlateNumber:'',freeMinutes:30,firstHourPrice:5,additionalHourPrice:3,dailyCapAmount:30})
const form=reactive<ResourceForm>(defaults());const title=computed(()=>({PARKING_LOT:'停车场',PARKING_SPACE:'车位',BILLING_RULE:'计费规则'}[type.value]??'资源'))
async function load(){loading.value=true;try{const r=await getAdminResources<Row>({resourceType:type.value,pageSize:100});rows.value=r.list;if(type.value==='PARKING_LOT')lots.value=r.list as ParkingLot[]}finally{loading.value=false}}
async function ensureLots(){if(!lots.value.length)lots.value=(await getAdminResources<ParkingLot>({resourceType:'PARKING_LOT',pageSize:100})).list}
async function open(row?:Row){await ensureLots();editingId.value=row?.id;Object.assign(form,defaults(),row??{},row?{}:{parkingLotId:lots.value[0]?.id});dialog.value=true}
function payload(){if(type.value==='PARKING_LOT')return{lotName:form.lotName,lotCode:form.lotCode,address:form.address,contactPhone:form.contactPhone,businessStartTime:form.businessStartTime,businessEndTime:form.businessEndTime,description:form.description,totalSpaces:form.totalSpaces,availableSpaces:form.availableSpaces,status:form.status,temporaryPrice:form.temporaryPrice};if(type.value==='PARKING_SPACE')return{parkingLotId:form.parkingLotId,spaceCode:form.spaceCode,spaceType:form.spaceType,status:form.status,currentPlateNumber:form.currentPlateNumber};return{parkingLotId:form.parkingLotId,freeMinutes:form.freeMinutes,firstHourPrice:form.firstHourPrice,additionalHourPrice:form.additionalHourPrice,dailyCapAmount:form.dailyCapAmount,status:form.status}}
async function save(){if(type.value==='PARKING_LOT'&&(!form.lotName.trim()||!form.lotCode.trim()||!form.address.trim())){ElMessage.warning('请填写名称、编码和地址');return}if(type.value!=='PARKING_LOT'&&!form.parkingLotId){ElMessage.warning('请选择停车场');return}if(type.value==='PARKING_SPACE'&&!form.spaceCode.trim()){ElMessage.warning('请填写车位编号');return}await ElMessageBox.confirm(`确认${editingId.value?'更新':'创建'}${title.value}？`,'保存确认');await actOnAdminResource({resourceType:type.value,action:editingId.value?'UPDATE':'CREATE',id:editingId.value,payload:payload()});ElMessage.success(`${title.value}已保存`);dialog.value=false;await load()}
async function changeStatus(row:Row){await ElMessageBox.confirm('确认切换该资源状态？','状态确认',{type:'warning'});await actOnAdminResource({resourceType:type.value,action:'CHANGE_STATUS',id:row.id,payload:{status:row.status===1?0:1}});ElMessage.success('状态已更新');await load()}
async function remove(row:Row){await ElMessageBox.confirm('确定删除该资源？请先确认没有业务数据占用。','删除确认',{type:'warning'});await actOnAdminResource({resourceType:type.value,action:'DELETE',id:row.id});ElMessage.success('资源已删除');await load()}
function lotName(id?:number){return lots.value.find(l=>l.id===id)?.lotName??`停车场 #${id??'--'}`}
function statusLabel(row:Row){if(type.value==='PARKING_LOT')return LOT_STATUS[(row.status??0) as keyof typeof LOT_STATUS];if(type.value==='PARKING_SPACE')return SPACE_STATUS[(row.status??0) as keyof typeof SPACE_STATUS];return row.status===1?'生效':'停用'}
function spaceTypeLabel(value?:SpaceType){return value?SPACE_TYPE[value]:'--'}
onMounted(async()=>{await load();lots.value=rows.value as ParkingLot[]})
</script>
<template><div><h1 class="page-title">停车资源综合管理</h1><p class="page-subtitle">一个综合页面调用管理员资源接口管理停车场、车位和基础计费规则。</p><div class="panel"><el-tabs v-model="type" @tab-change="load"><el-tab-pane label="停车场" name="PARKING_LOT"/><el-tab-pane label="车位" name="PARKING_SPACE"/><el-tab-pane label="计费规则" name="BILLING_RULE"/></el-tabs><div class="toolbar"><el-button type="primary" @click="open()">新增{{ title }}</el-button><span class="text-muted">共 {{ rows.length }} 条</span></div><el-table v-loading="loading" :data="rows"><template v-if="type==='PARKING_LOT'"><el-table-column prop="lotName" label="停车场" min-width="170"/><el-table-column prop="lotCode" label="编码" width="130"/><el-table-column prop="address" label="地址" min-width="210"/><el-table-column label="营业时间" width="140"><template #default="{row}">{{ row.businessStartTime }}-{{ row.businessEndTime }}</template></el-table-column><el-table-column label="空闲/总数" width="110"><template #default="{row}">{{ row.availableSpaces }}/{{ row.totalSpaces }}</template></el-table-column></template><template v-else-if="type==='PARKING_SPACE'"><el-table-column label="停车场" min-width="180"><template #default="{row}">{{ lotName(row.parkingLotId) }}</template></el-table-column><el-table-column prop="spaceCode" label="车位编号" width="110"/><el-table-column label="类型" width="130"><template #default="{row}">{{ spaceTypeLabel(row.spaceType) }}</template></el-table-column><el-table-column prop="currentPlateNumber" label="当前车牌" width="120"/></template><template v-else><el-table-column label="停车场" min-width="180"><template #default="{row}">{{ lotName(row.parkingLotId) }}</template></el-table-column><el-table-column prop="freeMinutes" label="免费分钟" width="100"/><el-table-column prop="firstHourPrice" label="首小时" width="90"/><el-table-column prop="additionalHourPrice" label="后续/时" width="90"/><el-table-column prop="dailyCapAmount" label="日封顶" width="90"/></template><el-table-column label="状态" width="100"><template #default="{row}"><StatusTag :label="statusLabel(row)" :status="row.status===1?1:3"/></template></el-table-column><el-table-column label="操作" width="220" fixed="right"><template #default="{row}"><el-button text type="primary" @click="open(row)">编辑</el-button><el-button text type="warning" @click="changeStatus(row)">切换状态</el-button><el-button text type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="`${editingId?'编辑':'新增'}${title}`" width="min(620px,94vw)"><el-form :model="form" label-position="top"><template v-if="type==='PARKING_LOT'"><div class="two"><el-form-item label="名称" required><el-input v-model="form.lotName"/></el-form-item><el-form-item label="编码" required><el-input v-model="form.lotCode"/></el-form-item><el-form-item label="地址" required><el-input v-model="form.address"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactPhone"/></el-form-item><el-form-item label="营业开始"><el-time-select v-model="form.businessStartTime" start="00:00" step="00:30" end="23:30"/></el-form-item><el-form-item label="营业结束"><el-time-select v-model="form.businessEndTime" start="00:00" step="00:30" end="23:59"/></el-form-item></div><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item></template><template v-else-if="type==='PARKING_SPACE'"><el-form-item label="停车场" required><el-select v-model="form.parkingLotId" class="full-width"><el-option v-for="lot in lots" :key="lot.id" :label="lot.lotName" :value="lot.id"/></el-select></el-form-item><el-form-item label="车位编号" required><el-input v-model="form.spaceCode"/></el-form-item><el-form-item label="车位类型"><el-select v-model="form.spaceType" class="full-width"><el-option v-for="(label,value) in SPACE_TYPE" :key="value" :label="label" :value="value"/></el-select></el-form-item></template><template v-else><el-form-item label="停车场" required><el-select v-model="form.parkingLotId" class="full-width"><el-option v-for="lot in lots" :key="lot.id" :label="lot.lotName" :value="lot.id"/></el-select></el-form-item><div class="two"><el-form-item label="免费分钟"><el-input-number v-model="form.freeMinutes" :min="0"/></el-form-item><el-form-item label="首小时价格"><el-input-number v-model="form.firstHourPrice" :min="0" :precision="2"/></el-form-item><el-form-item label="后续每小时"><el-input-number v-model="form.additionalHourPrice" :min="0" :precision="2"/></el-form-item><el-form-item label="每日封顶"><el-input-number v-model="form.dailyCapAmount" :min="0" :precision="2"/></el-form-item></div></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.two{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}@media(max-width:650px){.two{grid-template-columns:1fr}}</style>
